<form method="GET" class="flex flex-wrap gap-4 items-end mb-7 text-sm"><label>Search<input name="q" value="{{ request('q') }}" maxlength="100" class="block border border-forest/25 rounded-lg p-3 mt-2"></label><label>Publication<select name="publication" class="block border border-forest/25 rounded-lg p-3 mt-2"><option value="">All</option><option value="published" @selected(request('publication')==='published')>Published</option><option value="draft" @selected(request('publication')==='draft')>Draft</option></select></label><button class="bg-forest text-white px-5 py-3 rounded-lg">Filter</button><a class="underline py-3" href="{{ url()->current() }}">Reset</a></form>
